def find_longest(numbers):
    def digit_count(n):
        return len(str(abs(n)))

    max_num = numbers[0]
    max_digits = digit_count(max_num)

    for num in numbers:
        current_digits = digit_count(num)
        if current_digits > max_digits:
            max_digits = current_digits
            max_num = num

    return max_num
